reference_solution:
def middleNode(head):
    slow = fast = head
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
    return slow

brute_force_solution:
def middleNode(head):
    n, cur = 0, head
    while cur:
        n += 1
        cur = cur.next
    cur = head
    for _ in range(n // 2):
        cur = cur.next
    return cur

